const transcriptPath = process.argv[2]
const outputPath = process.argv[3]
if (!transcriptPath || !outputPath) throw new Error('usage: build-agentic-os-transcript-review.mjs <rollout.jsonl> <output.json>')

const transcript = compileVisibleTranscript(transcriptPath)
const owners = transcript.messages.filter(message => message.role === 'user')
const ownerById = new Map(owners.map(message => [message.id, message]))
const reviewsById = new Map()
for (const item of REVIEWS) {
  if (reviewsById.has(item.messageId)) throw new Error(`duplicate curated review: ${item.messageId}`)
  const observed = ownerById.get(item.messageId)
  if (!observed) throw new Error(`curated review does not match a current owner message: ${item.messageId}`)
  if (observed.textSha256 !== item.textSha256) throw new Error(`curated review is stale for owner message: ${item.messageId}`)
  reviewsById.set(item.messageId, item)
}
const missing = owners.filter(message => !reviewsById.has(message.id))
const extra = [...reviewsById.keys()].filter(id => !ownerById.has(id))
if (missing.length || extra.length || reviewsById.size !== owners.length) {
  throw new Error(`curated review denominator mismatch: observed=${owners.length} reviewed=${reviewsById.size} missing=${missing.map(message => message.id).join(',')} extra=${extra.join(',')}`)
}

const sourceMessageIdsByTopic = new Map(Object.keys(TOPICS).map(topic => [topic, new Set()]))
for (const item of REVIEWS) {
  for (const targetRef of item.canonicalEffect.targetRefs) sourceMessageIdsByTopic.get(targetRef.slice('review-topic:'.length)).add(item.messageId)
}
const targetCatalog = Object.entries(TOPICS).map(([topic, [label, canonicalIntentIds]]) => ({
  ref: `review-topic:${topic}`,
  label,
  authority: 'reviewer-defined-topic-not-canon',
  canonicalIntentIds,
  sourceMessageIds: [...sourceMessageIdsByTopic.get(topic)],
  adjudication: canonicalIntentIds.length ? 'matched-to-protected-intent' : 'review-only-no-canon-effect',
}))

const ledger = {
  schemaVersion: 'arc-atlas-transcript-review-ledger-v1',
  authority: 'reviewed-interpretation-proposal-below-owner-message-and-protected-canon',
  threadId: transcript.threadId,
  ownerMessageSetSha256: transcript.coverage.ownerMessageSetSha256,
  reviewer: {
    identity: 'codex:repository-atlas-review',
    basis: 'explicit-message-by-message-review',
  },
  targetCatalog,
  reviews: owners.map(message => reviewsById.get(message.id)),
}
mkdirSync(path.dirname(path.resolve(outputPath)), { recursive: true })
writeFileSync(path.resolve(outputPath), `${JSON.stringify(ledger, null, 2)}\n`)
process.stdout.write(`${JSON.stringify({ status: 'review-ledger-built', ownerMessages: owners.length, ownerMessageSetSha256: ledger.ownerMessageSetSha256, output: path.resolve(outputPath) })}\n`)
